package com.pulselens.analytics.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="analysis_history") public class AnalysisRecord {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false) private Long userId;@Column(nullable=false) private String analysisType;@Column(length=1000) private String inputPreview;@Column(columnDefinition="LONGTEXT") private String resultJson;private long executionMs;@Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public String getAnalysisType(){return analysisType;}public void setAnalysisType(String v){analysisType=v;}public String getInputPreview(){return inputPreview;}public void setInputPreview(String v){inputPreview=v;}public String getResultJson(){return resultJson;}public void setResultJson(String v){resultJson=v;}public long getExecutionMs(){return executionMs;}public void setExecutionMs(long v){executionMs=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
